package Tv2.View;
import MainPage.View.Workspace;import java.awt.*;import java.util.List;import java.util.function.IntConsumer;import javax.swing.*;
public class SoDoHocPage extends Workspace {
 public record Cell(String label,Color color,String detail){}
 public record Slice(String label,int count,Color color){}
 public void render(List<Cell> cells,List<Slice> slices,IntConsumer click){JPanel all=new JPanel(new BorderLayout(8,8));all.setOpaque(false);JPanel grid=new JPanel(new GridLayout(0,6,8,8));grid.setBackground(BG);for(int i=0;i<cells.size();i++){Cell c=cells.get(i);int n=i;JButton b=new JButton(c.label());b.setBackground(c.color());b.setFont(new Font("Segoe UI",Font.BOLD,13));b.setFocusPainted(false);b.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(HocVienPage.LINE),BorderFactory.createEmptyBorder(10,4,10,4)));b.setOpaque(true);b.setToolTipText(c.detail());b.setPreferredSize(new Dimension(110,58));b.addActionListener(e->click.accept(n));grid.add(b);}JPanel wrap=new JPanel(new BorderLayout());wrap.setBackground(HocVienPage.BG);wrap.add(grid,BorderLayout.NORTH);JScrollPane scroll=new JScrollPane(wrap);scroll.setBorder(BorderFactory.createEmptyBorder());all.add(scroll,BorderLayout.CENTER);JPanel chart=new JPanel(new BorderLayout());chart.setBackground(Color.WHITE);chart.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(HocVienPage.LINE),BorderFactory.createEmptyBorder(12,12,12,12)));JComponent pie=new JComponent(){protected void paintComponent(Graphics g){super.paintComponent(g);Graphics2D a=(Graphics2D)g.create();a.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);int total=slices.stream().mapToInt(Slice::count).sum(),start=90,used=0,d=Math.min(getWidth()-20,getHeight()-20);if(total>0&&d>0){for(int i=0;i<slices.size();i++){Slice s=slices.get(i);used+=s.count();int end=90-(int)Math.round(360.0*used/total);a.setColor(s.color());a.fillArc((getWidth()-d)/2,10,d,d,start,end-start);a.setColor(Color.GRAY);a.drawArc((getWidth()-d)/2,10,d,d,start,end-start);start=end;}}a.dispose();}};pie.setPreferredSize(new Dimension(240,220));chart.add(pie,BorderLayout.NORTH);JPanel legend=new JPanel(new GridLayout(0,1));for(Slice s:slices){JLabel l=new JLabel(s.label()+": "+s.count());l.setOpaque(true);l.setBackground(s.color());l.setBorder(BorderFactory.createEmptyBorder(7,9,7,9));legend.add(l);}chart.add(legend,BorderLayout.CENTER);all.add(chart,BorderLayout.EAST);content(all);}
}
